/* 학습 해설
 * Level IRQ: 활성 수준·mask·ack·재개
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * level 신호는 장치가 활성 수준을 유지하는 동안 재발생할 수 있습니다. lock 뒤 mask_ack를 먼저 하고 may_run을 확인합니다. action 부재·disabled면 pending을 남기고 masked 상태로 끝납니다. 정상은 통계·event 뒤 cond_unmask를 수행해 thread 작업 여부에 맞춰 전달을 재개합니다.
 * 장치 pending을 지우는 callback과 controller ack를 구별하세요. mask→ack→handler→조건부 unmask 순서를 그리고 thread가 남은 경우를 함께 풉니다.
 */
void handle_level_irq(struct irq_desc *desc)
{
	raw_spin_lock(&desc->lock);
	mask_ack_irq(desc);

	if (!irq_may_run(desc))
		goto out_unlock;

	desc->istate &= ~(IRQS_REPLAY | IRQS_WAITING);

	/*
	 * If its disabled or no action available
	 * keep it masked and get out of here
	 */
	if (unlikely(!desc->action || irqd_irq_disabled(&desc->irq_data))) {
		desc->istate |= IRQS_PENDING;
		goto out_unlock;
	}

	kstat_incr_irqs_this_cpu(desc);
	handle_irq_event(desc);

	cond_unmask_irq(desc);

out_unlock:
	raw_spin_unlock(&desc->lock);

/* 학습 해설
 * 조건부 EOI: oneshot와 늦춘 완료 통지
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * ONESHOT가 아니면 EOI 후 반환합니다. ONESHOT이면 disabled가 아니고 masked이며 thread bit가 없을 때 EOI 후 unmask합니다. 그렇지 않으면 EOI_THREADED가 없을 때만 EOI입니다. EOI_THREADED는 남은 thread 처리 뒤 완료 통지를 미루는 정책으로 연결됩니다.
 * oneshot·disabled·masked·thread bit·EOI flag의 조합을 표로 그립니다. callback 횟수 검산과 실제 controller 완료 의미는 구별합니다.
 */
static void cond_unmask_eoi_irq(struct irq_desc *desc, struct irq_chip *chip)
{
	if (!(desc->istate & IRQS_ONESHOT)) {
		chip->irq_eoi(&desc->irq_data);
		return;
	}
	/*
	 * We need to unmask in the following cases:
	 * - Oneshot irq which did not wake the thread (caused by a
	 *   spurious interrupt or a primary handler handling it
	 *   completely).
	 */
	if (!irqd_irq_disabled(&desc->irq_data) &&
	    irqd_irq_masked(&desc->irq_data) && !desc->threads_oneshot) {
		chip->irq_eoi(&desc->irq_data);
		unmask_irq(desc);
	} else if (!(chip->flags & IRQCHIP_EOI_THREADED)) {
		chip->irq_eoi(&desc->irq_data);
	}
}

