/* 학습 해설
 * Fast EOI NMI: 단일 action 계약
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * NMI flow는 per-CPU 통계를 증가하고 trace entry→단일 action handler→trace exit를 수행합니다. eoi callback이 있으면 호출합니다. 주석은 NMI가 공유되지 않아 action 하나라는 계약을 명시합니다. action NULL guard나 일반 descriptor lock이 없는 만큼 등록과 NMI-safe callback 조건이 중요합니다.
 * 일반 shared IRQ의 action loop와 비교합니다. 단일 action·NMI 문맥 제한·선택적 EOI를 표시하고 이 함수가 sleep 가능한 작업을 허용한다고 가정하지 않습니다.
 */
void handle_fasteoi_nmi(struct irq_desc *desc)
{
	struct irq_chip *chip = irq_desc_get_chip(desc);
	struct irqaction *action = desc->action;
	unsigned int irq = irq_desc_get_irq(desc);
	irqreturn_t res;

	__kstat_incr_irqs_this_cpu(desc);

	trace_irq_handler_entry(irq, action);
	/*
	 * NMIs cannot be shared, there is only one action.
	 */
	res = action->handler(irq, action->dev_id);
	trace_irq_handler_exit(irq, action, res);

	if (chip->irq_eoi)
		chip->irq_eoi(&desc->irq_data);
}
EXPORT_SYMBOL_GPL(handle_fasteoi_nmi);

