 * descriptor lock 안에서 설정 bits를 clear/set합니다. 기존 trigger를 저장하고 irq_data의 balance·percpu·trigger·level·move bits를 내린 뒤 새 settings로 다시 세웁니다. 새 trigger mask가 NONE이 아니면 이를 택하고 아니면 기존 trigger를 유지합니다. 이미 활성인데 NOAUTOEN 설정은 경고하지만 작업을 계속합니다.
 * settings와 irq_data에 같은 정책이 표현되는 두 위치를 그립니다. 기존 trigger 유지 branch와 특정 bits 재구성을 순서대로 주석 달아봅니다.
 */
void irq_modify_status(unsigned int irq, unsigned long clr, unsigned long set)
{
	unsigned long flags, trigger, tmp;
	struct irq_desc *desc = irq_get_desc_lock(irq, &flags, 0);

	if (!desc)
		return;

	/*
	 * Warn when a driver sets the no autoenable flag on an already
	 * active interrupt.
	 */
	WARN_ON_ONCE(!desc->depth && (set & _IRQ_NOAUTOEN));

	irq_settings_clr_and_set(desc, clr, set);

	trigger = irqd_get_trigger_type(&desc->irq_data);

	irqd_clear(&desc->irq_data, IRQD_NO_BALANCING | IRQD_PER_CPU |
		   IRQD_TRIGGER_MASK | IRQD_LEVEL | IRQD_MOVE_PCNTXT);
	if (irq_settings_has_no_balance_set(desc))
		irqd_set(&desc->irq_data, IRQD_NO_BALANCING);
	if (irq_settings_is_per_cpu(desc))
		irqd_set(&desc->irq_data, IRQD_PER_CPU);
	if (irq_settings_can_move_pcntxt(desc))
		irqd_set(&desc->irq_data, IRQD_MOVE_PCNTXT);

