 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * DEPRECATED_IRQ_CPU_ONOFFLINE 구성에서 활성 IRQ 번호를 순회합니다. descriptor가 없으면 건너뛰고 irqsave lock 안에서 chip·online callback을 확인합니다. ONOFFLINE_ENABLED가 없거나 IRQ가 disabled가 아니면 callback을 호출합니다. flag가 있으면 enabled IRQ만 통지하는 정책입니다.
 * 활성 IRQ 목록과 CPU 온라인 사건을 연결합니다. chip flag·disabled의 네 조합을 풀이하고 callback 제공·잠금 수명 조건을 적습니다.
 */
void irq_cpu_online(void)
{
	struct irq_desc *desc;
	struct irq_chip *chip;
	unsigned long flags;
	unsigned int irq;

	for_each_active_irq(irq) {
		desc = irq_to_desc(irq);
		if (!desc)
			continue;

		raw_spin_lock_irqsave(&desc->lock, flags);

		chip = irq_data_get_irq_chip(&desc->irq_data);
		if (chip && chip->irq_cpu_online &&
		    (!(chip->flags & IRQCHIP_ONOFFLINE_ENABLED) ||
		     !irqd_irq_disabled(&desc->irq_data)))
			chip->irq_cpu_online(&desc->irq_data);

		raw_spin_unlock_irqrestore(&desc->lock, flags);
	}
}

