/* 학습 해설
 * IRQ 기본 affinity: boot CPU 보존
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * SMP boot 인자 irqaffinity=의 문자열을 CPU list로 parse합니다. mask storage를 준비하고 현재 boot CPU를 반드시 추가해 비어 있거나 부적절한 mask가 boot CPU까지 제외하지 않도록 합니다. parse 반환 값은 여기서 검사하지 않고 setup 처리 결과는 1입니다. 실제 문자열 문법은 cpulist_parse 구현 계약입니다.
 * boot CPU 0과 입력 {2,3}이면 결과 {0,2,3}인 예를 풉니다. 입력 parse 성공 여부와 boot CPU 보존 정책을 분리하고 이 함수가 전체 affinity 강제 설정이라고 설명하지 않습니다.
 */
static int __init irq_affinity_setup(char *str)
{
	alloc_bootmem_cpumask_var(&irq_default_affinity);
	cpulist_parse(str, irq_default_affinity);
	/*
	 * Set at least the boot cpu. We don't want to end up with
	 * bugreports caused by random commandline masks
	 */
	cpumask_set_cpu(smp_processor_id(), irq_default_affinity);
	return 1;
}
__setup("irqaffinity=", irq_affinity_setup);

static void __init init_irq_default_affinity(void)
{
	if (!cpumask_available(irq_default_affinity))
		zalloc_cpumask_var(&irq_default_affinity, GFP_NOWAIT);
	if (cpumask_empty(irq_default_affinity))
		cpumask_setall(irq_default_affinity);
}
