/* 학습 해설
 * Descriptor SMP 초기화: 복사와 pending clear
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * 입력 affinity가 NULL이면 irq_default_affinity를 선택해 descriptor affinity에 복사합니다. GENERIC_PENDING_IRQ면 pending mask를 지우고 NUMA면 node를 기록합니다. 입력 mask 포인터를 그대로 보관하는 대신 준비한 mask storage에 값을 복사합니다. UP 대체는 작업이 없습니다.
 * 입력 mask와 descriptor storage를 두 객체로 그립니다. NULL fallback·pending 초기화·NUMA field 조건을 구분하고 실제 할당은 alloc_masks가 담당함을 연결합니다.
 */
static void desc_smp_init(struct irq_desc *desc, int node,
			  const struct cpumask *affinity)
{
	if (!affinity)
		affinity = irq_default_affinity;
	cpumask_copy(desc->irq_common_data.affinity, affinity);

#ifdef CONFIG_GENERIC_PENDING_IRQ
	cpumask_clear(desc->pending_mask);
#endif
#ifdef CONFIG_NUMA
	desc->irq_common_data.node = node;
#endif
}

static void free_masks(struct irq_desc *desc)
{
#ifdef CONFIG_GENERIC_PENDING_IRQ
	free_cpumask_var(desc->pending_mask);
#endif
	free_cpumask_var(desc->irq_common_data.affinity);
#ifdef CONFIG_GENERIC_IRQ_EFFECTIVE_AFF_MASK
	free_cpumask_var(desc->irq_common_data.effective_affinity);
#endif
}

