/* 학습 해설
 * Descriptor 기본 상태: 사용 전 안전한 초기값
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * handler/MSI context를 NULL로 두고 irq_data.common·번호·no_irq_chip을 연결합니다. default settings에 disabled·masked를 세우고 bad handler와 depth 1을 설정합니다. IRQ·unhandled·total 통계를 0으로 만들고 name=NULL·owner를 저장하며 모든 possible CPU의 irqstat를 0으로 초기화한 뒤 SMP mask 정책을 적용합니다.
 * 새 descriptor의 chip·handler·depth·bits와 context를 표로 그립니다. 할당과 실제 IRQ 활성화를 구분하고 아직 요청하지 않은 IRQ가 정상 handler로 실행되지 않는 기본 상태를 읽습니다.
 */
static void desc_set_defaults(unsigned int irq, struct irq_desc *desc, int node,
			      const struct cpumask *affinity, struct module *owner)
{
	int cpu;

	desc->irq_common_data.handler_data = NULL;
	desc->irq_common_data.msi_desc = NULL;

	desc->irq_data.common = &desc->irq_common_data;
	desc->irq_data.irq = irq;
	desc->irq_data.chip = &no_irq_chip;
	desc->irq_data.chip_data = NULL;
	irq_settings_clr_and_set(desc, ~0, _IRQ_DEFAULT_INIT_FLAGS);
	irqd_set(&desc->irq_data, IRQD_IRQ_DISABLED);
	irqd_set(&desc->irq_data, IRQD_IRQ_MASKED);
	desc->handle_irq = handle_bad_irq;
	desc->depth = 1;
	desc->irq_count = 0;
	desc->irqs_unhandled = 0;
	desc->tot_count = 0;
	desc->name = NULL;
	desc->owner = owner;
	for_each_possible_cpu(cpu)
		*per_cpu_ptr(desc->kstat_irqs, cpu) = (struct irqstat) { };
	desc_smp_init(desc, node, affinity);
}

/* 학습 해설
 * Maple Tree IRQ 저장소: 빈 연속 범위 탐색
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * sparse_irqs는 ALLOC_RANGE·LOCK_EXTERN·USE_RCU flag의 Maple Tree이고 외부 sparse_irq_lock을 사용합니다. MA_STATE로 탐색 상태를 만들고 from부터 MAX_SPARSE_IRQS까지 cnt 길이 빈 영역을 찾습니다. 실패는 ENOSPC, 성공은 mas.index입니다. 이 함수 자체에 mutex 획득은 없습니다.
 * 사용 번호 {2,3,7}, from 2, cnt 2의 첫 빈 연속 영역을 손으로 풉니다. 검색 storage는 실제 Maple Tree이고 단순 bitmap으로 원문을 대체하지 않습니다. 자세한 tree 알고리즘은 해당 수업과 연결합니다.
 */
static int irq_find_free_area(unsigned int from, unsigned int cnt)
{
	MA_STATE(mas, &sparse_irqs, 0, 0);

	if (mas_empty_area(&mas, from, MAX_SPARSE_IRQS, cnt))
		return -ENOSPC;
	return mas.index;
}

static unsigned int irq_find_at_or_after(unsigned int offset)
{
	unsigned long index = offset;
	struct irq_desc *desc;

	guard(rcu)();
	desc = mt_find(&sparse_irqs, &index, nr_irqs);

	return desc ? irq_desc_get_irq(desc) : nr_irqs;
}

static void irq_insert_desc(unsigned int irq, struct irq_desc *desc)
{
	MA_STATE(mas, &sparse_irqs, irq, irq);
	WARN_ON(mas_store_gfp(&mas, desc, GFP_KERNEL) != 0);
}

