		     unsigned int flags,
		     const struct cpumask *affinity,
		     struct module *owner)
{
	desc->kstat_irqs = alloc_percpu(struct irqstat);
	if (!desc->kstat_irqs)
		return -ENOMEM;

	if (alloc_masks(desc, node)) {
		free_percpu(desc->kstat_irqs);
		return -ENOMEM;
	}

	raw_spin_lock_init(&desc->lock);
	lockdep_set_class(&desc->lock, &irq_desc_lock_class);

/* 학습 해설
 * Descriptor 자원 초기화: 잠금·waitqueue·RCU
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * per-CPU irqstat를 할당하고 masks 할당 실패면 percpu를 반환합니다. spinlock 초기화와 공통 lockdep class, request_mutex·thread waitqueue·기본 값·입력 flags·resend를 설정합니다. SPARSE 구성은 kobject와 rcu_head도 초기화합니다. 단계 실패는 ENOMEM이며 성공 0입니다.
 * 통계→masks→잠금·대기→기본 상태→선택 수명의 순서를 그립니다. init과 활성화가 다르며 초기화만으로 IRQ thread가 실행되지 않는 점을 기록합니다.
 */
static int init_desc(struct irq_desc *desc, int irq, int node,
		     unsigned int flags,
		     const struct cpumask *affinity,
		     struct module *owner)
{
	desc->kstat_irqs = alloc_percpu(struct irqstat);
	if (!desc->kstat_irqs)
		return -ENOMEM;

	if (alloc_masks(desc, node)) {
		free_percpu(desc->kstat_irqs);
		return -ENOMEM;
	}

	raw_spin_lock_init(&desc->lock);
	lockdep_set_class(&desc->lock, &irq_desc_lock_class);
	mutex_init(&desc->request_mutex);
	init_waitqueue_head(&desc->wait_for_threads);
	desc_set_defaults(irq, desc, node, affinity, owner);
	irqd_set(&desc->irq_data, flags);
	irq_resend_init(desc);
#ifdef CONFIG_SPARSE_IRQ
	kobject_init(&desc->kobj, &irq_kobj_type);
	init_rcu_head(&desc->rcu);
#endif

/* 학습 해설
 * Sysfs CPU 통계: bounded 쉼표 출력
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * kobject에서 container_of로 descriptor를 얻어 possible CPU별 통계를 쉼표로 출력합니다. 매번 PAGE_SIZE-ret만큼 scnprintf를 사용하고 끝에 줄바꿈을 추가합니다. CPU별 count를 한 값으로 합산하는 출력이 아닙니다. snapshot 전체 동시 일치 보장은 본문에 없습니다.
 * CPU count {3,7}이면 3,7과 newline인 문자열을 써봅니다. bounded formatting과 모든 CPU 통계의 원자 snapshot은 다른 속성임을 구분합니다.
 */
static ssize_t per_cpu_count_show(struct kobject *kobj,
				  struct kobj_attribute *attr, char *buf)
{
	struct irq_desc *desc = container_of(kobj, struct irq_desc, kobj);
	ssize_t ret = 0;
	char *p = "";
	int cpu;

	for_each_possible_cpu(cpu) {
		unsigned int c = irq_desc_kstat_cpu(desc, cpu);

		ret += scnprintf(buf + ret, PAGE_SIZE - ret, "%s%u", p, c);
		p = ",";
	}

	ret += scnprintf(buf + ret, PAGE_SIZE - ret, "\n");
	return ret;
}
IRQ_ATTR_RO(per_cpu_count);

static ssize_t chip_name_show(struct kobject *kobj,
			      struct kobj_attribute *attr, char *buf)
{
	struct irq_desc *desc = container_of(kobj, struct irq_desc, kobj);
	ssize_t ret = 0;
